// Populated places (data/world/places.json, generated by tools/) used to name new cities after the
// nearest real town. The file may be missing: then every city is a "Settlement cx,cy".
//
// File shape: { generatedAt, source, places: [[name, x, y, pop, country], ...] } sorted by pop desc,
// x/y in tile coordinates.

import fs from 'node:fs';
import { log, warn } from './util.ts';

export interface Place {
  name: string;
  x: number;
  y: number;
  pop: number;
  country: string;
}

/** Only places within this many tiles of the chunk centre are candidates (else: nearest regardless). */
const NAME_RADIUS = 160;
/** Score = dist - POP_WEIGHT * log10(pop + 1): a bigger town wins over a slightly nearer hamlet. */
const POP_WEIGHT = 0.5;

export class Places {
  readonly places: Place[] = [];

  load(file: string): void {
    if (!fs.existsSync(file)) {
      warn(`${file} not found; new cities will be named "Settlement cx,cy" (run the places generator in tools/)`);
      return;
    }
    try {
      const raw = JSON.parse(fs.readFileSync(file, 'utf8')) as { places?: unknown[] };
      if (!Array.isArray(raw.places)) throw new Error('no places array');
      for (const row of raw.places) {
        if (!Array.isArray(row) || row.length < 4) continue;
        const [name, x, y, pop, country] = row as unknown[];
        if (typeof name !== 'string' || typeof x !== 'number' || typeof y !== 'number' || typeof pop !== 'number') continue;
        this.places.push({ name: name.trim(), x, y, pop: Math.max(0, pop), country: typeof country === 'string' ? country : '' });
      }
      log(`Loaded ${this.places.length} populated places from ${file}`);
    } catch (e) {
      warn(`Could not load ${file}: ${(e as Error).message}; new cities will be named "Settlement cx,cy"`);
      this.places.length = 0;
    }
  }

  /**
   * Best place name for a city founded at tile (x,y): among places within NAME_RADIUS the lowest
   * dist - 0.5*log10(pop+1); if none in range, the nearest place; null if there are no places at all.
   */
  nearestName(x: number, y: number): string | null {
    let best: Place | null = null,
      bestScore = Infinity;
    let nearest: Place | null = null,
      nearestD = Infinity;
    for (const pl of this.places) {
      const dx = pl.x - x,
        dy = pl.y - y;
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d < nearestD) {
        nearestD = d;
        nearest = pl;
      }
      if (d > NAME_RADIUS) continue;
      const score = d - POP_WEIGHT * Math.log10(pl.pop + 1);
      if (score < bestScore) {
        bestScore = score;
        best = pl;
      }
    }
    const pick = best ?? nearest;
    return pick && pick.name ? pick.name : null;
  }
}
